// @vitest-environment node
// T13200 - Real-zip manifests (names + CRC + size + duration, no media). Counts come from
// EPIC.md "Survey of 7 real zips". Generated by scripts/veo_manifest.py; a missing manifest is
// a visible todo, never a silent pass.
import { describe, it, expect } from 'vitest';
import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { parseEntries, mergeMoments, withDurations } from './index.js';

const DIR = join(process.cwd(), 'src/utils/veoHighlights/manifests');
// manifest file -> [parsed mp4s, after dedupe, moments]
const EXPECTED = {
  'rebels': [41, 40, 35],
  'sd-surf': [88, 87, 73],
  'beach-fc': [44, 43, 35],
  'scrimmage-10_4_25': [59, 59, 45],
  'legends-1st-half': [32, 31, 27],
  'legends-2nd-half': [30, 30, 25],
  'la-breakers': [35, 35, 30],
};

describe('real-zip manifests', () => {
  for (const [name, [parsedN, dedupN, momentN]] of Object.entries(EXPECTED)) {
    const path = join(DIR, `${name}.json`);
    if (!existsSync(path)) { it.todo(`${name}: manifest not generated yet (scripts/veo_manifest.py)`); continue; }
    it(`${name}: zero skips, ${parsedN} -> ${dedupN} -> ${momentN}`, () => {
      const m = JSON.parse(readFileSync(path, 'utf8'));
      const { parsed, skipped } = parseEntries(m.entries);
      expect(skipped).toEqual([]);
      expect(parsed).toHaveLength(parsedN);
      const durations = Object.fromEntries(m.entries.map((e) => [e.name, e.duration_s]));
      const r = mergeMoments(withDurations(parsed, durations));
      expect(r.afterDedupe).toBe(dedupN);
      expect(r.moments).toHaveLength(momentN);
    });
  }

  it('rebels: the folded groups are the goals at 883, 1631, 4827, 4966 s, Goal first', () => {
    const path = join(DIR, 'rebels.json');
    if (!existsSync(path)) return; // covered by the todo above
    const m = JSON.parse(readFileSync(path, 'utf8'));
    const { parsed } = parseEntries(m.entries);
    const r = mergeMoments(withDurations(parsed, Object.fromEntries(m.entries.map((e) => [e.name, e.duration_s]))));
    const folded = r.moments.filter((x) => x.entries.length > 1);
    expect(folded.map((x) => x.labels[0])).toEqual(['Goal', 'Goal', 'Goal', 'Goal']);
    expect(folded.map((x) => x.stamp_s)).toEqual([883, 1631, 4827, 4966]);
  });
});
